    /// <summary>The main loop of bcrypt for 4 hashes: 2^cost times, expand with the key, then with the salt.</summary>
    [MethodImpl(MethodImplOptions.AggressiveOptimization)]
    private static void Loop4(uint* st, uint* key, uint* saltKey, int iterations)
    {
        for (var it = 0; it < iterations; it++)
        {
            Expand4(st, key);
            Expand4(st, saltKey);
        }
    }

    /// <summary>The most hashes one thread runs at once.</summary>
    internal const int MaxLanes = 4;

    /// <summary>The main loop for 1..MaxLanes hashes.</summary>
    private static void RunLoop(int lanes, uint* st, uint* key, uint* saltKey, int iterations)
    {
        switch (lanes)
        {
            case 1: Loop1(st, key, saltKey, iterations); break;
            case 2: Loop2(st, key, saltKey, iterations); break;
            case 3: Loop3(st, key, saltKey, iterations); break;
            default: Loop4(st, key, saltKey, iterations); break;
        }
    }
